import{_ as a,o,c as t,a0 as s}from"./chunks/framework.BL79I5mR.js";const S=JSON.parse('{"title":"CaSS Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"dev/cass-configuration/index.md","filePath":"dev/cass-configuration/README.md"}'),r={name:"dev/cass-configuration/index.md"};function i(c,e,d,l,n,h){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="cass-configuration" tabindex="-1">CaSS Configuration <a class="header-anchor" href="#cass-configuration" aria-label="Permalink to &quot;CaSS Configuration&quot;">​</a></h1><p>There are a number of environment variables that can be configured to change the ways that CaSS behaves.</p><h2 id="https" tabindex="-1"><code>HTTPS</code> <a class="header-anchor" href="#https" aria-label="Permalink to &quot;`HTTPS`&quot;">​</a></h2><p>Should CaSS use HTTPS. Defaults to <code>false</code>.</p><h2 id="elasticsearch-endpoint" tabindex="-1"><code>ELASTICSEARCH_ENDPOINT</code> <a class="header-anchor" href="#elasticsearch-endpoint" aria-label="Permalink to &quot;`ELASTICSEARCH_ENDPOINT`&quot;">​</a></h2><p>URL for the elastic search service. Defaults to <code>http://localhost:9200</code>.</p><h2 id="cass-loopback" tabindex="-1"><code>CASS_LOOPBACK</code> <a class="header-anchor" href="#cass-loopback" aria-label="Permalink to &quot;`CASS_LOOPBACK`&quot;">​</a></h2><p>URL for the CaSS API. Defaults to <code>http://localhost/api/</code> or <code>https://localhost/api/</code>, depending on if https is enabled.</p><h2 id="cass-loopback-proxy" tabindex="-1"><code>CASS_LOOPBACK_PROXY</code> <a class="header-anchor" href="#cass-loopback-proxy" aria-label="Permalink to &quot;`CASS_LOOPBACK_PROXY`&quot;">​</a></h2><p>Optional URL for the loopback proxy. Used when the endpoint that CaSS uses to talk to itself is different than how it represents itself, for example the loopback proxy may be on localhost.</p><h2 id="cass-oidc-enabled" tabindex="-1"><code>CASS_OIDC_ENABLED</code> <a class="header-anchor" href="#cass-oidc-enabled" aria-label="Permalink to &quot;`CASS_OIDC_ENABLED`&quot;">​</a></h2><p>Should CaSS use OpenID Connect. Defaults to <code>false</code>.</p><h2 id="cass-oidc-issuer-base-url" tabindex="-1"><code>CASS_OIDC_ISSUER_BASE_URL</code> <a class="header-anchor" href="#cass-oidc-issuer-base-url" aria-label="Permalink to &quot;`CASS_OIDC_ISSUER_BASE_URL`&quot;">​</a></h2><p>URL for the OpenID Connect issuer, e.g. Keycloak. Defaults to <code>https://dev.keycloak.eduworks.com/auth/realms/test-realm/</code>.</p><h2 id="cass-oidc-client-id" tabindex="-1"><code>CASS_OIDC_CLIENT_ID</code> <a class="header-anchor" href="#cass-oidc-client-id" aria-label="Permalink to &quot;`CASS_OIDC_CLIENT_ID`&quot;">​</a></h2><p>ID of the client being used in OpenID Connect. Defaults to <code>cass</code>.</p><h2 id="cass-oidc-secret" tabindex="-1"><code>CASS_OIDC_SECRET</code> <a class="header-anchor" href="#cass-oidc-secret" aria-label="Permalink to &quot;`CASS_OIDC_SECRET`&quot;">​</a></h2><p>Secret key for the above client.</p><h2 id="cass-oidc-base-url" tabindex="-1"><code>CASS_OIDC_BASE_URL</code> <a class="header-anchor" href="#cass-oidc-base-url" aria-label="Permalink to &quot;`CASS_OIDC_BASE_URL`&quot;">​</a></h2><p>Base URL for login and logout API when using OpenID Connect. Defaults to <code>http://localhost/</code>.</p><h2 id="cass-jwt-enabled" tabindex="-1"><code>CASS_JWT_ENABLED</code> <a class="header-anchor" href="#cass-jwt-enabled" aria-label="Permalink to &quot;`CASS_JWT_ENABLED`&quot;">​</a></h2><p>Should CaSS use JWT for authentication. Defaults to <code>false</code>.</p><h2 id="cass-jwt-secret" tabindex="-1"><code>CASS_JWT_SECRET</code> <a class="header-anchor" href="#cass-jwt-secret" aria-label="Permalink to &quot;`CASS_JWT_SECRET`&quot;">​</a></h2><p>Secet key for JWT. Defaults to <code>cass</code>.</p><h2 id="cass-jwt-algorithm" tabindex="-1"><code>CASS_JWT_ALGORITHM</code> <a class="header-anchor" href="#cass-jwt-algorithm" aria-label="Permalink to &quot;`CASS_JWT_ALGORITHM`&quot;">​</a></h2><p>JWT Algorithm to use. Defaults to <code>HS256</code>.</p><h2 id="cass-banner-message" tabindex="-1"><code>CASS_BANNER_MESSAGE</code> <a class="header-anchor" href="#cass-banner-message" aria-label="Permalink to &quot;`CASS_BANNER_MESSAGE`&quot;">​</a></h2><p>Optional message to display in banners along the top and bottom of the CaSS Editor.</p><h2 id="cass-banner-text-color" tabindex="-1"><code>CASS_BANNER_TEXT_COLOR</code> <a class="header-anchor" href="#cass-banner-text-color" aria-label="Permalink to &quot;`CASS_BANNER_TEXT_COLOR`&quot;">​</a></h2><p>Optional color for the banner message text. Defaults to the CaSS Editor theme colors.</p><h2 id="cass-banner-background-color" tabindex="-1"><code>CASS_BANNER_BACKGROUND_COLOR</code> <a class="header-anchor" href="#cass-banner-background-color" aria-label="Permalink to &quot;`CASS_BANNER_BACKGROUND_COLOR`&quot;">​</a></h2><p>Optional color for banner background. Defaults to the CaSS Editor theme colors.</p><h2 id="cass-external-endpoint" tabindex="-1"><code>CASS_EXTERNAL_ENDPOINT</code> <a class="header-anchor" href="#cass-external-endpoint" aria-label="Permalink to &quot;`CASS_EXTERNAL_ENDPOINT`&quot;">​</a></h2><p>Optional URL for a CaSS instance to use as the endpoint for creating alignments/relations, instead of this CaSS instance.</p><h2 id="cass-replication-endpoint" tabindex="-1"><code>CASS_REPLICATION_ENDPOINT</code> <a class="header-anchor" href="#cass-replication-endpoint" aria-label="Permalink to &quot;`CASS_REPLICATION_ENDPOINT`&quot;">​</a></h2><p>Optional URL of another CaSS instance to replicate data to.</p><h2 id="cass-replication-ppk" tabindex="-1"><code>CASS_REPLICATION_PPK</code> <a class="header-anchor" href="#cass-replication-ppk" aria-label="Permalink to &quot;`CASS_REPLICATION_PPK`&quot;">​</a></h2><p>The key for the above replication endpoint.</p><h2 id="profile-repository-cache" tabindex="-1"><code>PROFILE_REPOSITORY_CACHE</code> <a class="header-anchor" href="#profile-repository-cache" aria-label="Permalink to &quot;`PROFILE_REPOSITORY_CACHE`&quot;">​</a></h2><p>Should CaSS cache computed profiles in a repository. Defaults to <code>false</code>.</p><h2 id="profile-cache" tabindex="-1"><code>PROFILE_CACHE</code> <a class="header-anchor" href="#profile-cache" aria-label="Permalink to &quot;`PROFILE_CACHE`&quot;">​</a></h2><p>Should CaSS cache computed profiles in memory. Defaults to <code>false</code>.</p><h2 id="profile-ppk" tabindex="-1"><code>PROFILE_PPK</code> <a class="header-anchor" href="#profile-ppk" aria-label="Permalink to &quot;`PROFILE_PPK`&quot;">​</a></h2><p>Optional private key for CaSS to use when querying for a profile.</p><h2 id="default-plugins" tabindex="-1"><code>DEFAULT_PLUGINS</code> <a class="header-anchor" href="#default-plugins" aria-label="Permalink to &quot;`DEFAULT_PLUGINS`&quot;">​</a></h2><p>Optional array of URLs to plugins to be made available within the CaSS Editor. If deployed at the same URL as CaSS, the base of the URL can be omitted: <code>[&quot;/my-feature&quot;]</code> is transformed to <code>&quot;https://my-cass-instance/my-feature&quot;</code>. Available in 1.5.6+.</p><h2 id="motd-message" tabindex="-1"><code>MOTD_MESSAGE</code> <a class="header-anchor" href="#motd-message" aria-label="Permalink to &quot;`MOTD_MESSAGE`&quot;">​</a></h2><p>Optional message to display as a popup when users open the CaSS Editor.</p><h2 id="motd-title" tabindex="-1"><code>MOTD_TITLE</code> <a class="header-anchor" href="#motd-title" aria-label="Permalink to &quot;`MOTD_TITLE`&quot;">​</a></h2><p>Optional title for the above message.</p><h2 id="disabled-adapters" tabindex="-1"><code>DISABLED_ADAPTERS</code> <a class="header-anchor" href="#disabled-adapters" aria-label="Permalink to &quot;`DISABLED_ADAPTERS`&quot;">​</a></h2><p>Optional comma separated list of adapters to disable in CaSS. Valid options include: <code>asn, case, ceasn, jsonld, badge, xapi, profile</code>.</p><h2 id="max-connections" tabindex="-1"><code>MAX_CONNECTIONS</code> <a class="header-anchor" href="#max-connections" aria-label="Permalink to &quot;`MAX_CONNECTIONS`&quot;">​</a></h2><p>Optional limit on the number of concurrent connections to the CaSS server. Should be an integer value.</p><h2 id="log-filtered-categories" tabindex="-1"><code>LOG_FILTERED_CATEGORIES</code> <a class="header-anchor" href="#log-filtered-categories" aria-label="Permalink to &quot;`LOG_FILTERED_CATEGORIES`&quot;">​</a></h2><p>Optional comma separated list of logging categories to disable. Valid options include: <code>sys, auth, msg, fs, net, stor, adap, prof</code>.</p><h2 id="log-filtered-severities" tabindex="-1"><code>LOG_FILTERED_SEVERITIES</code> <a class="header-anchor" href="#log-filtered-severities" aria-label="Permalink to &quot;`LOG_FILTERED_SEVERITIES`&quot;">​</a></h2><p>Optional comma separated list of logging severities to disable. Valid options include: <code>EMERGENCY, ALERT, CRITICAL, ERROR, WARNING, NOTICE, INFO, DEBUG</code>.</p><h2 id="log-filtered-messages" tabindex="-1"><code>LOG_FILTERED_MESSAGES</code> <a class="header-anchor" href="#log-filtered-messages" aria-label="Permalink to &quot;`LOG_FILTERED_MESSAGES`&quot;">​</a></h2><p>Optional comma separated list of specific log messages to disable.</p><h2 id="smtp-host" tabindex="-1"><code>SMTP_HOST</code> <a class="header-anchor" href="#smtp-host" aria-label="Permalink to &quot;`SMTP_HOST`&quot;">​</a></h2><p>Optional SMTP server to use in order to send emergency email warnings regarding the CaSS instance.</p><h2 id="smtp-port" tabindex="-1"><code>SMTP_PORT</code> <a class="header-anchor" href="#smtp-port" aria-label="Permalink to &quot;`SMTP_PORT`&quot;">​</a></h2><p>Optional SMTP port for the above SMTP server. Defaults to <code>587</code>.</p><h2 id="smtp-user" tabindex="-1"><code>SMTP_USER</code> <a class="header-anchor" href="#smtp-user" aria-label="Permalink to &quot;`SMTP_USER`&quot;">​</a></h2><p>Optional username for the above SMTP server.</p><h2 id="smtp-pass" tabindex="-1"><code>SMTP_PASS</code> <a class="header-anchor" href="#smtp-pass" aria-label="Permalink to &quot;`SMTP_PASS`&quot;">​</a></h2><p>Optional password for the above SMTP server.</p><h2 id="smtp-recipients" tabindex="-1"><code>SMTP_RECIPIENTS</code> <a class="header-anchor" href="#smtp-recipients" aria-label="Permalink to &quot;`SMTP_RECIPIENTS`&quot;">​</a></h2><p>Optional comma separated list of email addresses which should receive email notifications from the above SMTP server.</p>',70)])])}const u=a(r,[["render",i]]);export{S as __pageData,u as default};
